from kosika.memory import MemoryStore, MAX_ENTRIES
s=MemoryStore()
s.entries('m').update({str(i):i for i in range(MAX_ENTRIES)})
result=s.remember('m','0','updated')
assert result=={'key':'0','entries':MAX_ENTRIES}
assert s.recall('m','0')=={'found':True,'value':'updated'}
assert len(s.entries('m'))==MAX_ENTRIES
s=MemoryStore()
s.entries('m').update({str(i):i for i in range(MAX_ENTRIES)})
before=dict(s.entries('m'))
try:s.remember('m','x','new')
except RuntimeError as exc:assert str(exc)==f"Memory 'm' is full ({MAX_ENTRIES} entries)"
else:raise AssertionError('new key accepted')
assert s.entries('m')==before
assert s.recall('m','x')=={'found':False,'value':None}
print('PASS')

from pathlib import Path
from tempfile import TemporaryDirectory
from kosika.memory import MemoryStore, MAX_KEY_LENGTH

with TemporaryDirectory() as directory:
    store = MemoryStore(directory)
    original = {'note': 'keep me'}
    assert store.remember('notes', 'valid', original) == {'key': 'valid', 'entries': 1}
    path = Path(directory) / 'notes.json'
    before = path.read_bytes()
    files = sorted(Path(directory).iterdir())
    try:
        store.remember('notes', '', {'note': 'replacement'})
    except RuntimeError as exc:
        assert str(exc) == f'A memory key must have 1 to {MAX_KEY_LENGTH} characters'
    else:
        raise AssertionError('empty key was accepted')
    assert store.entries('notes') == {'valid': original}
    assert store.recall('notes', 'valid') == {'found': True, 'value': original}
    assert store.recall('notes', '') == {'found': False, 'value': None}
    assert path.read_bytes() == before
    assert sorted(Path(directory).iterdir()) == files
    reopened = MemoryStore(directory)
    assert reopened.entries('notes') == {'valid': original}
    assert reopened.recall('notes', 'valid') == {'found': True, 'value': original}
    print('PASS')

from kosika.memory import MemoryStore, MAX_KEY_LENGTH
s = MemoryStore()
s.remember('notes', 'seed', {'value': 7})
assert s.recall('notes', '') == {'found': False, 'value': None}
assert s.recall('notes', 'seed') == {'found': True, 'value': {'value': 7}}
assert s.recall('notes', 'missing') == {'found': False, 'value': None}
try:
    s.remember('notes', '', {'value': 8})
except RuntimeError as exc:
    assert str(exc) == f'A memory key must have 1 to {MAX_KEY_LENGTH} characters'
else:
    raise AssertionError('empty-key remember did not raise')
assert s.entries('notes') == {'seed': {'value': 7}}

